local function union(...)
    local result, seen = {}, {}
    for index = 1, select("#", ...) do
        for _, scriptName in ipairs(select(index, ...)) do
            if not seen[scriptName] then seen[scriptName] = true; table.insert(result, scriptName) end
        end
    end
    return result
end

Catalog.groups.commercialVan = union(Catalog.groups.commercial, Catalog.groups.van)
Catalog.groups.military = union(Catalog.groups.militaryCar, Catalog.groups.militaryTruck, Catalog.groups.militaryTrailer)
Catalog.groups.modern = union(Catalog.groups.civilian, Catalog.groups.compact)
Catalog.groups.normal = union(Catalog.groups.civilian)
Catalog.groups.offroad = union(Catalog.groups.suv, Catalog.groups.pickup)
Catalog.groups.prisonPolice = union(Catalog.groups.prison, Catalog.groups.police)
Catalog.groups.race = union(Catalog.groups.sports)

function Catalog.copy(groupName)
    return union(Catalog.groups[groupName] or {})
end

function Catalog.combine(...)
    local inputs = {}
    for index = 1, select("#", ...) do table.insert(inputs, Catalog.groups[select(index, ...)] or {}) end
    return union(unpack(inputs))
end

function Catalog.weight(groupName, scriptName, zoneName)
    local weights = Catalog.weights[groupName]
    if weights and weights[scriptName] ~= nil then return weights[scriptName] end
    local rarity = Catalog.rarityWeights[scriptName] or 1
    local sourceWeights = Catalog.zoneWeights[scriptName]
    local zoneKey = type(zoneName) == "string" and string.lower(zoneName) or nil
    if zoneKey then
        local groupHasSourceWeight = false
        for _, candidate in ipairs(Catalog.groups[groupName] or {}) do
            local candidateWeights = Catalog.zoneWeights[candidate]
            if candidateWeights and candidateWeights[zoneKey] ~= nil then groupHasSourceWeight = true; break end
        end
        if sourceWeights and sourceWeights[zoneKey] ~= nil then
            local sourceWeight = sourceWeights[zoneKey]
            if rarity < 1 then return math.min(sourceWeight * rarity, rarity) end
            return sourceWeight
        elseif sourceWeights and groupHasSourceWeight then
            return 0 -- explicitly zoned vehicles do not leak into a different source zone
        end
    end
    return rarity
end

function Catalog.wreckedWeight(groupName, scriptName, zoneName)
    local weights = Catalog.weights[groupName .. "Wreck"]
    if weights and weights[scriptName] ~= nil then return weights[scriptName] end
    local rarity = Catalog.rarityWeights[scriptName] or 1
    local sourceWeights = Catalog.zoneWeights[scriptName]
    local zoneKey = type(zoneName) == "string" and string.lower(zoneName) or nil
    if zoneKey then
        local groupHasSourceWeight = false
        for _, candidate in ipairs(Catalog.wreckedGroups[groupName] or {}) do
            local candidateWeights = Catalog.zoneWeights[candidate]
            if candidateWeights and candidateWeights[zoneKey] ~= nil then groupHasSourceWeight = true; break end
        end
        if sourceWeights and sourceWeights[zoneKey] ~= nil then
            local sourceWeight = sourceWeights[zoneKey]
            if rarity < 1 then return math.min(sourceWeight * rarity, rarity) end
            return sourceWeight
        elseif sourceWeights and groupHasSourceWeight then
            return 0
        end
    end
    return rarity
end

local function weightedList(groupName, candidates, slots, zoneName, wrecked)
    slots = math.max(1, math.floor(tonumber(slots) or 250))
    local entries, total = {}, 0
    for _, scriptName in ipairs(candidates or {}) do
        local weight = wrecked and Catalog.wreckedWeight(groupName, scriptName, zoneName) or Catalog.weight(groupName, scriptName, zoneName)
        if weight and weight > 0 then total = total + weight; table.insert(entries, { script = scriptName, weight = weight }) end
    end
    if total <= 0 then return {} end
    local result, remainders, assigned = {}, {}, 0
    for index, entry in ipairs(entries) do
        local exact = slots * entry.weight / total
        local count = math.floor(exact)
        assigned = assigned + count
        remainders[index] = { index = index, value = exact - count }
        for _ = 1, count do table.insert(result, entry.script) end
    end
    table.sort(remainders, function(a, b) if a.value == b.value then return a.index < b.index end return a.value > b.value end)
    for index = 1, slots - assigned do table.insert(result, entries[remainders[index].index].script) end
    return result
end

function Catalog.weightedCopy(groupName, slots, zoneName)
    local special = Catalog.weightedGroups[groupName]
    if special and (slots == nil or slots == 1000) then
        local copy = {}
        for _, scriptName in ipairs(special) do table.insert(copy, scriptName) end
        return copy
    end
    return weightedList(groupName, Catalog.groups[groupName] or {}, slots, zoneName, false)
end

function Catalog.weightedList(groupName, candidates, slots, zoneName)
    return weightedList(groupName, candidates, slots, zoneName, false)
end

function Catalog.weightedCombine(slots, ...)
    local count = select("#", ...)
    if count == 0 then return {} end
    slots = math.max(count, math.floor(tonumber(slots) or 250))
    local result = {}
    for index = 1, count do
        local groupName = select(index, ...)
        local groupSlots = math.floor(slots / count) + (index <= (slots % count) and 1 or 0)
        for _, scriptName in ipairs(Catalog.weightedCopy(groupName, groupSlots)) do table.insert(result, scriptName) end
    end
    return result
end

function Catalog.wreckedWeightedCopy(groupName, slots)
    return weightedList(groupName, Catalog.wreckedGroups[groupName] or {}, slots, nil, true)
end

return Catalog
